EDITS = json.loads("{\"README.md\":[[0,1,\"# YuuZPrime — TMDB to VOD Playlist\\n\\nModifikasi: YuuZGilakPrompt. Basis asli: TMDB-To-VOD-Playlist by gogetta69. Lisensi CC BY-NC 4.0 tetap berlaku. Modul khusus film dewasa telah dihapus. Gunakan hanya sumber media yang berizin.\\n\"],[7,8,\"\"],[21,26,\"\"],[91,92,\"\"],[117,118,\"\"]],\"config.php\":[[43,46,\"\"]],\"generate_live_playlist.php\":[[12,19,\"    $playlistUrl = 'http://drewlive24.duckdns.org:8081/DrewLive/MergedCleanPlaylist.m3u8';\\n\"]],\"play.php\":[[57,60,\"\\tif (intval($movieId) > 10000000) { http_response_code(404); exit(); }\\n\"],[142,142,\"        if (!is_array($movieData) || !empty($movieData['adult'])) { http_response_code(404); exit(); }\\n\"],[390,390,\"        if (!is_array($seriesData) || !empty($seriesData['adult'])) { http_response_code(404); exit(); }\\n\"],[581,729,\"\"],[2508,2511,\"\\tif($type === 'movies'){\\n\"],[7539,7540,\"\"]],\"player_api.php\":[[88,96,\"\"],[168,187,\"\"],[215,247,\"\"],[254,255,\"\"],[295,299,\"\\tif (intval($vodId) > 10000000) { http_response_code(404); exit(); }\\n\"],[303,303,\"    if (!is_array($details) || !empty($details['adult'])) { http_response_code(404); exit(); }\\n\"],[426,427,\"    $details = json_decode($fetchDetails, true);\\n    if (!is_array($details) || !empty($details['adult'])) { http_response_code(404); exit(); }\\n\"],[725,773,\"\"]]}")
EXPECTED = '017de6543e1f6aa9b5eec9e116061676d9eace57601a0948cf40c976826a6537'
root = Path('backend')
if root.exists():
    raise SystemExit('Refusing to overwrite an existing backend')

def get(item):
    name, sha = item
    url = 'https://raw.githubusercontent.com/gogetta69/TMDB-To-VOD-Playlist/' + REV + '/' + quote(name, safe='/')
    for attempt in range(3):
        try:
            with urlopen(Request(url, headers={'User-Agent':'YuuZPrime-verified-import'}), timeout=100) as r:
                data = r.read()
            break
        except Exception:
            if attempt == 2: raise
            time.sleep(2 ** attempt)
    assert hashlib.sha1(('blob %d\0' % len(data)).encode()+data).hexdigest() == sha, name
    if name in EDITS:
        lines = data.splitlines(keepends=True)
        for i,j,replacement in reversed(EDITS[name]):
            lines[i:j] = [replacement.encode()]
        data = b''.join(lines)
    return name, data

with tempfile.TemporaryDirectory() as tmp:
    stage=Path(tmp)/'backend'
    hashes={}
    with ThreadPoolExecutor(max_workers=5) as ex:
        for name,data in ex.map(get,FILES):
            p=stage/name
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_bytes(data)
            hashes[name]=hashlib.sha256(data).hexdigest()
    manifest=hashlib.sha256(''.join(f'{n}\t{hashes[n]}\n' for n in sorted(hashes)).encode()).hexdigest()
    assert len(hashes)==114 and manifest==EXPECTED, (len(hashes),manifest)
    shutil.copytree(stage,root)
print('Verified: all 114 files match the sanitized archive.')
